local quests = WordHunterWoW_QuestDataByFlavor.classic.deDE
quests[8735] = { title = "Die Verderbnis des Alptraums", description = "Ihr müsst zu den vier Traumportalen von Azeroth reisen und Euch jeweils ein Verderbnisfragment des Alptraums beschaffen. Die Drachkin, die in dieser Gegend hausen, werden derartige Fragmente bei sich tragen. Kommt zu mir zurück, sobald Ihr diese Fragmente eingesammelt habt.", objectives = "Reist zu den vier Portalen des smaragdgrünen Traums in Azeroth und sammelt dort jeweils ein Verderbnisfragment des Alptraums ein. Kehrt zu Bewahrer Remulos bei der Mondlichtung zurück, sobald Ihr diese Aufgabe erfüllt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8736] = { title = "Der Alptraum offenbart sich", description = "Wir müssen gegen Eranikus mit Bedacht vorgehen. Wir sollen ihn erlösen und nicht zerstören.\n\nTyrande ist bereits auf dem Weg, um uns bei dieser Aufgabe zu unterstützen. Wir müssen die Attacken des Drachen überstehen und Nachthafen vor der sicheren Zerstörung bewahren.\n\nSeid auf der Hut! Ihr und Eure Verbündeten seid unsere einzige Hoffnung.", objectives = "Verteidigt Nachthafen gegen Eranikus. Bewahrer Remulos darf dabei nicht ums Leben kommen und Eranikus darf nicht getötet werden. Verteidigt Euch. Erwartet Tyrande.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8737] = { title = "Azurblauer Templer", description = "Die Schattenhammerkultisten und die von ihnen verehrten Elementarfürsten stellen eine dauerhafte Bedrohung für unsere Operationen in Silithus dar. Trotz der neuen Gegnermassen in Ahn'Qiraj können wir es uns nicht erlauben, unsere Wachposten und Einsätze gegen den äußeren Feind zu verringern.\n\nFindet einen Weg, um einen azurblauen Templer auf unsere Existenzebene zu beschwören und zerstört ihn.", objectives = "Beschwört und vernichtet einen azurblauen Templer. Erstattet anschließend Bericht bei Bor Wildmähne auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz I, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8738] = { title = "Späherbericht des Regalschwarms", description = "Wir haben unsere besten Späher bis weit in die Schwarmbauten der Silithiden ausgesendet, um Informationen zu sammeln. Späher Landion hat die Aktivitäten der Silithiden im Regalschwarm nun schon seit Tagen beobachtet. Findet ihn und besorgt Euch einen schriftlichen Bericht. Wir müssen so schnell wie möglich auf diese Informationen reagieren können, $n.", objectives = "Setzt Euch mit dem cenarischen Späher Landion innerhalb des Regalschwarmbaus in Verbindung und bringt den Späherbericht des Regalschwarms zu Windruferin Prachthorn auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz VII, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8739] = { title = "Späherbericht des Ashischwarms", description = "Wir haben unsere besten Späher bis weit in die Schwarmbauten der Silithiden ausgesendet. Späherin Jalia hat die Aktivitäten der Silithiden im Ashischwarm nun schon seit Tagen beobachtet. Findet sie und besorgt Euch einen schriftlichen Bericht. Wir müssen so schnell wie möglich auf diese Informationen reagieren können, $n.", objectives = "Setzt Euch mit der cenarischen Späherin Jalia innerhalb des Ashischwarmbaus in Verbindung und bringt den Späherbericht des Ashischwarms zu Windruferin Prachthorn auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz VIII, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8740] = { title = "Marodeure des Schattenhammers", description = "Es wurden mehrfach berittene Gruppen des Schattenhammers gesichtet, die außerhalb der Reichweite unserer Truppen in Burg Cenarius kleinere Patrouillen und Karawanen angreifen.\n\nFindet und vernichtet die Zwielichtmarodeure, gemeinsam mit ihrer Anführerin, einer furchterregenden Kriegerin namens Morna. Meldet Euch anschließend bei Windruferin Prachthorn.", objectives = "Tötet Zwielichtmarodeurin Morna und 2 Zwielichtmarodeure. Erstattet anschließend Bericht bei Windruferin Prachthorn. Ihr benötigt auch den taktischen Einsatz IX, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8741] = { title = "Der Held kehrt zurück", description = "Der Bewahrer erwartet Eure Rückkehr, $n. Bringt den grünen Szeptersplitter zu Anachronos in den Höhlen der Zeit.", objectives = "Bringt den grünen Szeptersplitter zu Anachronos in den Höhlen der Zeit.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
