quests[8857] = { title = "Geheimnisse des Kolosses - Ashi", description = "Ich suche nach schlachterprobten Abenteurern, die für mich eine Fragmentprobe vom Koloss des Ashischwarms zu Glotz in Beutebucht bringen. Nein, nein, Ihr braucht Euch nicht einmal in die Nähe dieses Giganten zu wagen. Nehmt einfach eine von meinen Proben und beeilt Euch. Verrottet nutzt sie Glotz nicht viel!", objectives = "Bringt das Fragment vom Koloss des Ashischwarms zu Glotz Widrikus in Beutebucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8858] = { title = "Geheimnisse des Kolosses - Regal", description = "Ich würde nichts lieber tun, als Schlickfaust dieses verdammte Fragment in sein fettes Maul zu stopfen. Stattdessen stecke ich hier fest und sammle Proben von dieser zu groß geratenen Kakerlake! In Anbetracht ihrer Größe, werde ich hier wohl noch eine Weile beschäftigt sein.\n\nNehmt diese Probe und bringt sie für mich zu Schlickfaust... und beeilt Euch, $C. Er zahlt auch sehr gut!\n\nAlso, ab zur Thoriumspitze in die Sengende Schlucht.", objectives = "Bringt das Fragment vom Koloss des Regalschwarms zu Aufseher Schlickfaust in die Sengende Schlucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8859] = { title = "Geheimnisse des Kolosses - Zora", description = "Meine Leute hätte es beinahe erwischt, als sie diese Probe beschafft haben. Ihr müsst Euch unbedingt beeilen! Lord Maxwell Tyrosus wartet bereits voller Ungeduld auf eine frische Fragmentprobe. Er geht davon aus, dass uns die Geheimnisse dieses Kolosses im Kampf gegen die Geißel sehr von Nutzen sein werden!\n\nWieso seid Ihr noch hier!? Zur Kapelle des Hoffnungsvollen Lichts! Ja, ja, man wird Euch für diese Aufgabe großzügig entlohnen...", objectives = "Bringt das Fragment vom Koloss des Zoraschwarms zu Lord Maxwell Tyrosus an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8860] = { title = "Neujahrsfeier!", description = "In Sturmwind wird das neue Jahr ganz groß gefeiert! Den ganzen Tag lang gibt es kostenlosen Hochprozentigen und nachts ein fantastisches Feuerwerk! Das wird sicher ein Riesenspaß... allerdings findet heute auch in Beutebucht eine Neujahrsfeier statt. Ich wette, dort ist sogar noch mehr los!\n\nEgal! Jedenfalls braucht Gastwirtin Allison in Sturmwind eine Ladung Kokelwälder Festtagsspeisen, um alle Partylöwen satt in das neue Jahr zu bringen. Würdet Ihr mir den Gefallen tun und die Vorräte für mich abliefern?\n\nDanke, $n! Ihr findet Gastwirtin Allison in der Güldenen Rose, drüben im Handelsdistrikt von Sturmwind.", objectives = "Bringt die Vorräte von Kokelwälder zu Gastwirtin Allison in Sturmwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8861] = { title = "Neujahrsfeier!", description = "In Thunder Bluff wird das neue Jahr ganz groß gefeiert! Den ganzen Tag lang gibt es kostenlos was Hochprozentiges zu trinken und nachts eine fantastische Feuerwerksschau! Das wird sicherlich ein Riesenspaß… allerdings findet auch in Booty Bay eine Neujahrsfeier statt. Ich wette, dort ist noch viel mehr los!\n\nEgal! Jedenfalls braucht Gastwirtin Pala eine Ladung Kokelwälder Festtagsspeisen, um alle Partylöwen satt in das neue Jahr zu bringen. Würdet Ihr mir den Gefallen tun und die Vorräte für mich abliefern?\n\nDanke, $N! Ihr findet Gastwirtin Pala in der Taverne nahe der Brücke zur Anhöhe der Jäger.", objectives = "Bringt die Vorräte von Kokelwälder zu Gastwirtin Pala in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
