quests[8921] = { title = "Der Ektoplasmadestillierer", description = "Ah, Ihr seid an meinem letzten Projekt interessiert... Dem extradimensionalen Geisterdetektor! Dummerweise sind mir die Geldmittel und Hilfskräfte ausgegangen\n\nIhr sagt, dass Ihr mir aushelfen wollt? Sehr gut! Zunächst müssen wir einen Apparat bauen, der die Essenz des Todes absaugen kann! Einen Ektoplasmadestillierer zu konstruieren wird allerdings nicht ganz einfach sein, $n.\n\nIhr müsst mir einen Arkanitwandler, einige große ewige Essenzen und Steinschuppenöl bringen. Außerdem brauche ich noch Vulkanasche aus den Lavatümpeln in der Brennenden Steppe, um einen Filter zu konstruieren.", objectives = "Kehrt mit einem empfindlichen Arkanitwandler, 4 großen ewigen Essenzen, 10 Flaschen Steinschuppenöl, 25 Einheiten Vulkanasche und 40 Gold im Gepäck zu Mux Manamix in Gadgetzan zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8922] = { title = "Ein übernatürlicher Apparat", description = "Ich muss einen Weg finden, mit Anthion Harmon zu sprechen... Oder genauer gesagt mit seinem Geist!\n\nIch kenne da einen Ingenieur, der eine gewisse Faszination für das Übernatürliche hegt. Er behauptet eine Maschine konstruieren zu können, die es ihm erlaubt mit den Toten zu kommunizieren!\n\nDas Blut, dass Ihr gesammelt habt, war für ihn bestimmt. Reist nach Gadgetzan und bringt es ihm als Bezahlung für seine Dienste!", objectives = "Bringt den versiegelten Blutbehälter zu Mux Manamix in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8923] = { title = "Ein übernatürlicher Apparat", description = "Ihr müsst wirklich verdammt mutig sein. Respekt, dass Ihr immer noch an der Sache dran seid. Oder vielleicht haben die Rüstungsteile, die ich Euch gegeben habe, ja Euer Interesse geweckt. Wo die herkamen gibt's noch mehr, wenn Ihr daran interessiert seid, mir erneut auszuhelfen.\n\nDie Giftproben, die Ihr gesammelt habt, sind für einen Bekannten von mir bestimmt, Mux Manamix, ein Ingenieur mit einem gewissen Interesse für das Übernatürliche. Seine neueste Erfindung soll es angeblich ermöglichen, mit den Toten zu kommunizieren! Meine letzte Hoffnung ist es, Anthion zu kontaktieren und mehr über meine Situation herauszufinden.", objectives = "Bringt den versiegelten Giftbehälter zu Mux Manamix in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8924] = { title = "Ektoplasmajagd", description = "Ein hervorragendes Stück Ingenieurarbeit, wenn ich das mal selbst so sagen darf! Ich fürchte allerdings, dass Ihr weit umherreisen werden müsst, um die Art schemenhafter Untoten zu finden, die wir benötigen.\n\nIhr müsst verstehen, dass verschiedenen Klimabedingungen Einfluss auf die spektrale Struktur der Toten haben. Die gequälten Nachtelfen in Silithus, die Geister der Hochgeborenen in Winterquell und die Geister und Banshees in den Östlichen Pestländern sollten uns mit den verschiedenen Sorten von Ektoplasma versorgen, die wir benötigen. Stellt auf jeden Fall den Destillierer in der Nähe auf, bevor Ihr sie bekämpft.", objectives = "Benutzt den Ektoplasmadestillierer in der Nähe von schemenhaften Untoten, um 12 Einheiten versengtes Ektoplasma in Silithus, 12 Einheiten gefrorenes Ektoplasma in Winterquell und 12 Einheiten stabiles Ektoplasma in den Östlichen Pestländern zu erhalten. Bringt das Ektoplasma dann mitsamt des Ektoplasmadestillierers zu Mux Manamix in Gadgetzan zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8925] = { title = "Eine portable Energiequelle", description = "Jetzt brauchen wir nur noch eine stabile und portable Energiequelle, um das Ektoplasma aktiv zu halten. Ich habe Gerüchte über einen machtvollen Elementar namens Magmafürst Bokk gehört, dessen Herz ein mächtiger Magmakern ist - eine schier unerschöpfliche Hitzequelle!\n\nMan sagt, dass er sich irgendwo in der Brennenden Steppe südlich des Schwarzfels herumtreibt. Bringt mir den Magmakern und wir werden genug Saft haben, um den extradimensionalen Geisterdetektor zu betreiben!", objectives = "Findet Magmafürst Bokk in der Brennenden Steppe, nehmt seinen Magmakern an Euch und bringt ihn zu Mux Manamix in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8926] = { title = "Die angemessene Entlohnung", description = "Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrechtzuerhalten. Bringt mir einen gewöhnlichen Gürtel und Handschuhe, von denen Ihr eine verbesserte Version wünscht. Ich kann Euch versichern, dass die Rüstung, die ich Euch geben werde, von weit höherer Qualität sein wird.", objectives = "Bringt Deliana in Eisenschmiede einen Gürtel des Wildherzens und ein Paar Handschuhe des Wildherzens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8927] = { title = "Die angemessene Entlohnung", description = "Ihr habt große Verlässlichkeit bewiesen, $n. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.", objectives = "Bringt Mokvar in Orgrimmar einen Gürtel des Wildherzens und ein Paar Handschuhe des Wildherzens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8928] = { title = "Ein verschlagener Händler", description = "Der Kern sollte uns mit genügend Energie zum Betreiben des Apparates versorgen, jetzt brauchen wir nur noch einen Brennstab, der diese Energie auch weiterleiten kann, ohne dabei zu schmelzen.\n\nIch habe in Winterquell mal einen Wichtel getroffen, der allerlei exotische Waren im Angebot hatte. Er hatte einen elementaren Brennstab, der einfach perfekt gewesen wäre. Ich könnte mich schwarz ärgern, dass ich den nicht gekauft habe.\n\nEr lebt in einer Höhle nahe dem Zugang zur Flüsternden Schlucht. Schleicht Euch hinein und seht zu, dass Ihr ihn findet.\n\nLasst Euch aber nicht von ihm übers Ohr hauen, zahlt ihm nicht mehr als 40 Goldstücke. Den Preis hat er mir damals angeboten!", objectives = "Sucht den Wichtel in der Höhle in der Nähe der Flüsternden Schlucht im Süden von Winterquell. Kauft ihm einen teufelselementaren Brennstab ab und kehrt zu Mux Manamix in Gadgetzan zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8929] = { title = "Suche nach Anthion", description = "Tja, wir haben wohl keine andere Wahl, als die Erfindung des Goblins auszuprobieren. Man sagt, dass Anthion von den untoten Horden Stratholmes niedergemetzelt wurde, als er versuchte, durch dessen Tore zu schreiten.\n\nVersucht den Apparat dort zu benutzen und herauszufinden, was auch immer Anthion wusste.", objectives = "Benutzt den extradimensionalen Geisterdetektor am Eingang zu Stratholme und sprecht mit dem Geist von Anthion Harmon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8930] = { title = "Suche nach Anthion", description = "Nun denn, $n. Jetzt müssen wir wohl die Erfindung des Goblins ausprobieren. Man sagt, dass Anthion von den untoten Horden Stratholmes niedergemäht wurde, als er versuchte, durch die Tore zu schreiten.\n\nVersucht den Apparat dort zu benutzen und findet heraus, was Anthion wusste.", objectives = "Benutzt den extradimensionalen Geisterdetektor am Eingang zu Stratholme und sprecht mit dem Geist von Anthion Harmon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8931] = { title = "Die angemessene Entlohnung", description = "Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrechtzuerhalten. Bringt mir einen gewöhnlichen Gürtel und Handschuhe, von denen Ihr eine verbesserte Version wünscht.", objectives = "Bringt Deliana in Eisenschmiede einen Bestienjägergürtel und ein Paar Bestienjägerhandschuhe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
