quests[8957] = { title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.", objectives = "Kehrt mit einem Paar Stiefel der Elemente, einem Kilt der Elemente und Schulterstücken der Elemente zu Mokvar in Orgrimmar zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8958] = { title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", objectives = "Kehrt mit einem Paar Sandalen der Furcht, Gamaschen der Furcht und einem Mantel der Furcht zu Deliana in Eisenschmiede zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8959] = { title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", objectives = "Kehrt mit einem Paar Stiefel der Ehre, Beinplatten der Ehre und einer Schiftung der Ehre zu Deliana in Eisenschmiede zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8960] = { title = "Bodleys trauriges Schicksal", description = "Wir müssen also die restlichen Stücke des Amuletts wiederbeschaffen? Bodley zu finden, könnte sich als schwierig erweisen. Er begab sich zurück in den Schwarzfels, um die Schwarzfelsspitze zu betreten, und kam nie zurück.\n\nIch würde Euch raten, den Geisterdetektor des Goblins mitzunehmen, denn ich befürchte, ihm könnte etwas Schlimmes zugestoßen sein.", objectives = "Reist zum Schwarzfels und benutzt den extradimensionalen Geisterdetektor, um Bodley nahe der Schwarzfelsspitze zu finden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8961] = { title = "Die drei Könige der Flammen", description = "Um Lord Valthalak zu beschwören, müssen wir zunächst die anderen beiden Drittel des Amuletts beschaffen. Und dafür brauchen wir wiederum ein Räuchergefäß und einige ganz spezielle Kohlen, die darin verbrannt werden müssen.\n\nEs gibt drei hochrangige Feuerelementare, von denen wir diese Kohlen bekommen können: Lord Incendius in den Schwarzfelstiefen, Feuerwache Glutseher in der Schwarzfelsspitze und der Fürst der Asche in Silithus. Sammelt die Kohlen aus ihren Überresten auf und kehrt dann mitsamt eines geheiligten Räuchergefäßes zu mir zurück. Ihr könnt das Räuchergefäß von der Argentumdämmerung kaufen, wenn sie Euch wohlwollend gesinnt ist.", objectives = "Bringt Bodley im Schwarzfels Incendius' Pyrophor, Glutsehers Glut, die Asche des Fürsten und ein geheiligtes Räuchergefäß.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8962] = { title = "Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, $C. Jetzt, da wir das Räuchergefäß haben und es anzünden können, brauchen wir noch ein paar weitere Dinge, die wir hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist, um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nMor Grauhuf, unser bester Druide, hatte viele enge Freunde im Zirkel des Cenarius, von denen einige den Silithiden zum Opfer gefallen sind. Ihr müsst mir einige Druidenüberreste von den Silithiden beschaffen, die den Bau des Regalschwarms im Südosten von Silithus bewohnen.", objectives = "Bringt Bodley im Schwarzfels einige Druidenüberreste.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8963] = { title = "Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, $C. Jetzt, da wir das Räuchergefäß haben und es anzünden können, brauchen wir noch ein paar weitere Dinge, die wir hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist, um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nIsalien, unsere Priesterin, wuchs in Sternenhauch in Winterquell auf. Ihr müsst mir ein Relikt von Sternenhauch von den Frosthagelriesen der Frosthauchschlucht im Süden von Winterquell bringen, die dafür bekannt sind, von Zeit zu Zeit den Norden unsicher zu machen.", objectives = "Bringt Bodley im Schwarzfels ein Relikt von Sternenhauch.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8964] = { title = "Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, $C. Jetzt, da wir das Räuchergefäß haben und es anzünden können, brauchen wir noch ein paar weitere Dinge, die wir hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist, um die Geister meiner verstorbenen Kameraden herbeizurufen.\n\nDie Geschwister, Jarien und Sothos, glaubten fest an die Lehren des Scharlachroten Kreuzzugs. Sie strebten danach, Ritter dieser abscheulichen Organisation zu werden. Geht zu Tyrs Hand, in den Östlichen Pestländern, und beschafft mir ein gleißendes Schwert des Zeloten von den dortigen Prätorianern.", objectives = "Bringt Bodley im Schwarzfels ein gleißendes Schwert des Zeloten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8965] = { title = "Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, $C. Jetzt, da wir das Räuchergefäß haben und es anzünden können, brauchen wir noch ein paar weitere Dinge, die wir hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist, um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nKormok, ein Ogernekromant, der unserem Bund angehörte, liebte es die Seelen der verbannten Toten von der Fegefeuerinsel, nahe der Südküste der Vorgebirge des Hügellands, herbeizurufen. Geht dorthin und beschafft mir etwas Seelenasche der Verbannten von ihren Überresten.", objectives = "Bringt Bodley im Schwarzfels etwas Seelenasche der Verbannten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8966] = { title = "Das linke Stück von Lord Valthalaks Amulett", description = "Ein Freund von mir, Mor Grauhuf, war der Erste, der Lord Valthalaks Amulett und dem darin enthaltenen, korrumpierenden Seelenfragment zum Opfer fiel. Nachdem wir Valthalaks Zauberbuch und Amulett gestohlen hatten, flohen wir um unser Leben aus dem oberen Teil der Schwarzfelsspitze. Während unserer überstürzten Flucht fiel Mor in den unteren Teil der Schwarzfelsspitze hinab.\n\nWir erfuhren später, dass er den Fall überlebt hatte und von Kriegsmeister Voone gefangen genommen und gefoltert worden war. Später schlichen sich spektrale Assassine in die Schwarzfelsspitze ein und erschlugen Mor vor Voones Augen.", objectives = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Mor Grauhuf zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8967] = { title = "Das linke Stück von Lord Valthalaks Amulett", description = "Wir erfuhren später, während wir alle unser Bestes taten, um zu überleben, dass Isalien, eine Nachtelfenpriesterin, die unserer Gruppe angehörte, in die Heimatstadt der Urahnen der Nachtelfen zurückgekehrt war - jetzt als Düsterbruch bekannt. Demzufolge, was uns berichtet wurde, zog es sie sowohl aus persönlichen Gründen dorthin zurück, als auch weil sie die Geheimnisse ihres Stücks des Amuletts ergründen wollte.\n\nAllerdings gelang es ihr nicht, dieses Wissen zu erlangen. Wie uns zugetragen wurde, wurde sie am Schrein von Eldretharr von Alzzin dem Wildformer und seinen Schergen in einen Hinterhalt gelockt.", objectives = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Isalien zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8968] = { title = "Das linke Stück von Lord Valthalaks Amulett", description = "Die Geschwister, Jarien und Sothos, beschlossen, sich dem Scharlachroten Kreuzzug anzuschließen, nachdem sich unser Söldnerbund aufgelöst hatte. Das linke Stück von Valthalaks Amulett nahmen sie mit sich. Ich war froh, sie los zu sein, aber jetzt brauchen wir dieses Stück zurück.\n\nUnseren Informationen zufolge, wurden sie vom Obersten Kreuzfahrer Dathrohan höchstpersönlich hingerichtet, da sie die Initiationsriten in seiner Kammer in der Scharlachroten Bastion nicht bestanden hatten. \n\nWie dem auch sei, wir... und damit meine ich Ihr, müssen dieses Stück des Amuletts zurückbekommen.", objectives = "Benutzt das Räuchergefäß der Beschwörung, um die Geister von Jarien und Sothos zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8969] = { title = "Das linke Stück von Lord Valthalaks Amulett", description = "Jetzt, wo wir alles beisammen haben was wir benötigen, wird es Zeit uns darüber zu unterhalten, wen Ihr beschwören werdet.\n\nKormok war ganz okay, für einen Oger, bis er sich der Nekromantie zuwandte. Von da ab wurde es für jeden im Bund ganz schön gruselig. Es überraschte also niemanden, dass er mit seinem Stück des Amuletts in sein neues Zuhause verschwand, Scholomance.\n\nAber selbst dort, oder vielleicht gerade dort, war er nicht vor den spektralen Assassinen sicher. Sie erschlugen ihn vor den Augen seines Meisters, Ras Frostraunen.", objectives = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Kormok zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8970] = { title = "Ich sehe die Insel Alcaz in Eurer Zukunft", description = "Wie ich schon sagte, $C, zu meinen Lebzeiten spielte ich mit dem Gedanken, ein Wahrsager zu werden. Aber damit kann man bei Weitem nicht so viel Profit machen, wie Ihr vielleicht denken würdet. Die Wahrsagerei kann nämlich ganz schön gefährlich sein und die Reagenzen sind selten und teuer. Aber ich weiß genug, um den Fundort des letzten Amulettstücks zu erahnen, und somit auch den Geist meines ehemaligen Kameraden.\n\nUnd deshalb benötige ich Eure Hilfe, $n. Ihr müsst zur Insel Alcaz vor der Küste der Düstermarschen reisen und Bluttang von den Naga der Strashaz, die dort leben, zusammensammeln.", objectives = "Bringt Bodley im Schwarzfels 20 Einheiten Bluttang von den Naga der Strashaz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8977] = { title = "Rückkehr zu Deliana", description = "War mir eine Freude, mit Euch zusammenzuarbeiten, $n. Hier ist das fertige Produkt.\n\nIch hoffe, dass es Euch bei Eurem Unterfangen behilflich sein wird. Verbreitet doch bitte die Kunde über meine hervorragenden Dienste, wenn es Euch nichts ausmacht. Ich hätte nichts gegen mehr Kundschaft einzuwenden.", objectives = "Bringt Deliana in Eisenschmiede den extradimensionalen Geisterdetektor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8978] = { title = "Rückkehr zu Mokvar", description = "War mir eine Freude, mit Euch zusammenzuarbeiten, $n. Hier ist das fertige Produkt.\n\nIch hoffe, dass es Euch bei Eurem Unterfangen behilflich sein wird. Verbreitet doch bitte die Kunde über meine hervorragenden Dienste, wenn es Euch nichts ausmacht. Ich hätte nichts gegen mehr Kundschaft einzuwenden.", objectives = "Kehrt mit dem extradimensionalen Geisterdetektor zu Mokvar in Orgrimmar zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8979] = { title = "Fenstads Visionen", description = "Ich denke, ich bin dem Grund für das merkwürdige Verhalten auf die Spur gekommen. Habt Ihr den Duft bemerkt, der in letzter Zeit den Gestank der Kanalisation überlagert? Das neue Duftwasser und Parfüm, das gerade so angesagt ist?\n\nUnsere Gedanken werden durch die Wirkung übelster Alchemie vernebelt.\n\nEs gibt nur einen Weg, um ganz sicher zu sein: Bringt meiner Freundin Apothekerin Zinge einen Flakon von dem Parfüm und dem Duftwasser. Die Königliche Apothekervereinigung wird die Wahrheit ans Licht bringen.\n\nIch werde Euch für Eure Ausgaben entschädigen, sobald Ihr zurückkommt.", objectives = "Bringt 1 Duftwasserflakon und 1 Parfümflakon zu Apothekerin Zinge im Apothekarium von Unterstadt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8980] = { title = "Zinges Einschätzung", description = "Das ist in der Tat unerwartet. Es sieht ganz so aus, als ob Fenstad doch noch auf etwas gestoßen sein könnte. Ich habe Spuren von Substanzen gefunden, die in Gedanken beinflussenden Tränken Verwendung finden.\n\nEs ist nicht ungewöhnlich, dass man in Parfüm derartige Spuren auffindet, allerdings sind einige der Zutaten, die ich in den Düften finden konnte, doch recht... merkwürdig. Es handelt sich hierbei um Alchemiekünste, die nur den Erfahrensten vorbehalten sind, so wie die Mitglieder der Königlichen Apothekervereinigung.", objectives = "Kehrt zu Fenstad Argyle außerhalb der Bank von Unterstadt zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8981] = { title = "Geschenkübergabe", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8982] = { title = "Verfolgung der Spur", description = "Wir müssen unbedingt herausfinden, wer der Lieferant ist. Ich habe sie erst kürzlich dabei beobachtet, wie sie einen Parfümflakon in ihrem Bündel verstaute. Sie sagte mir, dass sie es von Norman, dem Gastwirt, erworben hat.", objectives = "Sprecht mit Gastwirt Norman in Unterstadt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8983] = { title = "Verfolgung der Spur", description = "Ist etwas nicht in Ordnung mit meiner Ware? Nun, ich habe noch nie so viele Leute gesehen, die so sehr nach einer Sache verlangt haben.\n\nIch habe meine Bestände von einer Händlerin namens Mara Rennick. Sie ist neu in der Stadt.\n\nSie erwähnte, dass sie noch einige Waren beim Schneider im Magieviertel abzuliefern hätte.", objectives = "Sprecht mit Mara Rennick bei der Schneiderei im Magieviertel von Unterstadt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8984] = { title = "Lüftung des Geheimnisses", description = "Hört mal, die Taten eines abtrünnigen Apothekers sind nicht mein Problem. Sollte er tatsächlich unsere Sache untergraben, werde ich die Erste sein, die Euch die richtige Richtung weist.\n\nSollte er unschuldig sein, wird er nichts zu verbergen haben, oder?\n\nIch habe meine Ware beim Apotheker Staffron Lerent erworben. Er arbeitet im Vorgebirge des Hügellands, irgendwo hinter dem Rabenholdtanwesen. Ehrlich gesagt, kam er mir etwas komisch vor.", objectives = "Findet Apotheker Staffron Lerent hinter dem Rabenholdtanwesen im Vorgebirge des Hügellands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8985] = { title = "Mehr Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, $C. Jetzt, da wir wissen, wo das letzte Stück des Amuletts zu finden ist, brauchen wir noch ein paar weitere Dinge, die wir in das Räuchergefäß hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist, um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nIsalien, unsere Priesterin, wuchs in Sternenhauch in Winterquell auf. Ihr müsst mir ein Relikt von Sternenhauch von den Frosthagelriesen der Frosthauchschlucht im Süden von Winterquell bringen, die dafür bekannt sind, von Zeit zu Zeit den Norden unsicher zu machen.", objectives = "Bringt Bodley in der Schwarzfelsspitze ein Relikt von Sternenhauch.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8986] = { title = "Mehr Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, $C. Jetzt, da wir wissen, wo das letzte Stück des Amuletts zu finden ist, brauchen wir noch ein paar weitere Dinge, die wir in das Räuchergefäß hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist, um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nMor Grauhuf, unser bester Druide, hatte viele enge Freunde im Zirkel des Cenarius, von denen einige den Silithiden zum Opfer gefallen sind. Ihr müsst mir einige Druidenüberreste von den Silithiden beschaffen, die den Bau des Regalschwarms im Südosten von Silithus bewohnen.", objectives = "Bringt Bodley im Schwarzfels einige Druidenüberreste.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8987] = { title = "Mehr Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, $C. Jetzt, da wir wissen, wo das letzte Stück des Amuletts zu finden ist, brauchen wir noch ein paar weitere Dinge, die wir in das Räuchergefäß hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist, um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nDie Geschwister, Jarien und Sothos, glaubten fest an die Lehren des Scharlachroten Kreuzzugs. Sie strebten danach, Ritter dieser abscheulichen Organisation zu werden. Geht zu Tyrs Hand, in den Östlichen Pestländern, und beschafft mir ein gleißendes Schwert des Zeloten von den dortigen Prätorianern.", objectives = "Bringt Bodley im Schwarzfels ein gleißendes Schwert des Zeloten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8988] = { title = "Mehr Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, $C. Jetzt, da wir wissen, wo das letzte Stück des Amuletts zu finden ist, brauchen wir noch ein paar weitere Dinge, die wir in das Räuchergefäß hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist, um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nKormok, ein Ogernekromant, der unsererm Bund angehörte, liebte es die Seelen der verbannten Toten von der Fegefeuerinsel, nahe der Südküste der Vorgebirge des Hügellands, herbeizurufen. Geht dorthin und beschafft mir etwas Seelenasche der Verbannten von ihren Überresten.", objectives = "Bringt Bodley im Schwarzfels etwas Seelenasche der Verbannten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8989] = { title = "Das rechte Stück von Lord Valthalaks Amulett", description = "Ein Freund von mir, Mor Grauhuf, war der Erste, der Lord Valthalaks Amulett und dem darin enthaltenen, korrumpierenden Seelenfragment zum Opfer fiel. Nachdem wir Valthalaks Zauberbuch und Amulett gestohlen hatten, flohen wir um unser Leben aus dem oberen Teil der Schwarzfelsspitze. Während unserer überstürzten Flucht fiel Mor in den unteren Teil der Schwarzfelsspitze hinab.\n\nWir erfuhren später, dass er den Fall überlebt hatte und von Kriegsmeister Voone gefangen genommen und gefoltert worden war. Später schlichen sich spektrale Assassine in die Schwarzfelsspitze ein und erschlugen Mor vor Voones Augen.", objectives = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Mor Grauhuf zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8990] = { title = "Das rechte Stück von Lord Valthalaks Amulett", description = "Wir erfuhren später, während wir alle unser Bestes taten, um zu überleben, dass Isalien, eine Nachtelfenpriesterin, die unserer Gruppe angehörte, in die Heimatstadt der Urahnen der Nachtelfen zurückgekehrt war - jetzt als Düsterbruch bekannt. Demzufolge, was uns berichtet wurde, zog es sie sowohl aus persönlichen Gründen dorthin zurück, als auch weil sie die Geheimnisse ihres Stücks des Amuletts ergründen wollte.\n\nAllerdings gelang es ihr nicht, dieses Wissen zu erlangen. Wie uns zugetragen wurde, wurde sie am Schrein von Eldretharr von Alzzin dem Wildformer und seinen Schergen in einen Hinterhalt gelockt.", objectives = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Isalien zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8991] = { title = "Das rechte Stück von Lord Valthalaks Amulett", description = "Die Geschwister, Jarien und Sothos, beschlossen, sich dem Scharlachroten Kreuzzug anzuschließen, nachdem sich unser Söldnerbund aufgelöst hatte. Das rechte Stück von Valthalaks Amulett nahmen sie mit sich. Ich war froh, sie los zu sein, aber jetzt brauchen wir dieses Stück zurück.\n\nUnseren Informationen zufolge, wurden sie vom Obersten Kreuzfahrer Dathrohan höchstpersönlich hingerichtet, da sie die Initiationsriten in seiner Kammer in der Scharlachroten Bastion nicht bestanden hatten. \n\nWie dem auch sei, wir... und damit meine ich Ihr, müssen dieses Stück des Amuletts zurückbekommen.", objectives = "Benutzt das Räuchergefäß der Beschwörung, um die Geister von Jarien und Sothos zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8992] = { title = "Das rechte Stück von Lord Valthalaks Amulett", description = "Jetzt, wo wir alles beisammen haben, was wir benötigen, wird es Zeit, uns darüber zu unterhalten, wen Ihr als Nächstes beschwören werdet.\n\nKormok war für einen Oger ganz okay, bis er sich der Nekromantie zuwandte. Von da ab wurde es für jeden im Bund ganz schön gruselig. Es überraschte also niemanden, dass er mit seinem Stück des Amuletts in sein neues Zuhause verschwand, Scholomance.\n\nAber selbst dort, oder vielleicht gerade dort, war er nicht vor den spektralen Assassinen sicher. Sie erschlugen ihn vor den Augen seines Meisters, Ras Frostraunen.", objectives = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Kormok zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8993] = { title = "Geschenkübergabe", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8994] = { title = "Letzte Vorbereitungen", description = "Wir sind nun beinah bereit, $C. Ich brauche nur noch einige weitere Komponenten, um das Räuchergefäß darauf abzustimmen, Lord Valthalak herbeizurufen.\n\nFür den Anfang würde ich Euch darum bitten, Euch in die Schwarzfelsspitze zu begeben und die dort heimischen Orcs zu töten. Ihre Armschienen enthalten Metallspuren, die ich benötigen werde. Da diese Armschienen nur Spuren des Metalls enthalten, werde ich eine Menge von ihnen benötigen. Um den Abstimmungsprozess abzuschließen, brauche ich weiterhin noch ein Fläschchen der obersten Macht.\n\nViel Glück, $n!", objectives = "Bringt Bodley im Schwarzfels 40 Schwarzfelsarmschienen und ein Fläschchen der obersten Macht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8995] = { title = "Mea Culpa, Lord Valthalak", description = "Die nötigen Vorbereitungen sind nun getroffen, $n.\n\nZu seinen Lebzeiten bewohnte Lord Valthalak die Kammer, in der sich nun die Bestie aufhält. Geht dorthin und benutzt dann das Räuchergefäß der Beschwörung, um Lord Valthalak herbeizurufen. Es wird ihn wiederbeleben, also werdet Ihr ihn erneut töten müssen. Es wäre sinnvoll, zuerst die Bestie zu erledigen. Bringt außerdem genug Kameraden mit, um Euch durch den oberen Teil der Schwarzfelsspitze zu kämpfen.\n\nBenutzt, sobald Ihr ihn ausgeschaltet habt, das Amulett bei seiner Leiche. Nachdem seine Seele wieder vollständig ist, wird er es vermutlich zurückverlangen.\n\nViel Glück!", objectives = "Benutzt das Räuchergefäß der Beschwörung, um Lord Valthalak zu beschwören. Macht ihn unschädlich und benutzt dann Lord Valthalaks Amulett bei seiner Leiche. Danach werdet Ihr dem Geist von Lord Valthalak sein Amulett zurückgeben müssen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8996] = { title = "Rückkehr zu Bodley", description = "Ich werde Euch Eure Unverschämtheit dieses eine Mal vergeben, $C, da Ihr heute eine noble Tat vollbracht habt. Ihr habt mich wieder mit dem Rest meiner gestohlenen Seele vereint. Obgleich Eurer offensichtlich schwachen Natur, $R, habt Ihr den Mut bewiesen, über den jene, die es wagten mich zu bestehlen, nicht verfügten und vermutlich niemals werden.\n\nKehret schnell zu ihnen zurück, bevor ich es mir anders überlege und Euch dort niederstrecke, wo Ihr steht. Kehret zurück und richtet ihnen aus, dass sie vor mir sicher sind... Momentan zumindest.", objectives = "Bringt das Räuchergefäß der Beschwörung zurück zu Bodley im Schwarzfels.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8997] = { title = "Zurück zum Anfang", description = "Ich denke, nun wird es Zeit Lebewohl zu sagen, mein Freund. Ich werde immer hier sein, falls Ihr von Zeit zu Zeit mal mit mir reden wollt. Vielleicht ja, während Ihr auf Eure Kameraden wartet um der Schwarzfelsspitze einen Besuch abzustatten.\n\nGeht, bevor ich noch anfange zu heulen. Geht zu Deliana in Eisenschmiede zurück und erzählt ihr, was vorgefallen ist.", objectives = "Sprecht mit Deliana am Hohen Sitz von Eisenschmiede.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8998] = { title = "Zurück zum Anfang", description = "Ich denke, nun wird es Zeit Lebewohl zu sagen, mein Freund. Ich werde immer hier sein, falls Ihr von Zeit zu Zeit mal mit mir reden wollt. Vielleicht ja, während Ihr auf Eure Kameraden wartet um der Schwarzfelsspitze einen Besuch abzustatten.\n\nGeht, bevor ich noch anfange zu heulen. Geht zu Mokvar in Orgrimmar zurück und erzählt ihm, was vorgefallen ist.", objectives = "Sprecht mit Mokvar in der Feste Grommash im Tal der Weisheit von Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8999] = { title = "Das Beste gibt's zum Schluss", description = "Das ist ja eine unglaubliche Geschichte, $n! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.", objectives = "Gebt Deliana Eure Gugel des Wildherzens und Eure Weste des Wildherzens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9000] = { title = "Das Beste gibt's zum Schluss", description = "Das ist ja eine unglaubliche Geschichte, $n! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.", objectives = "Gebt Deliana Eure Bestienjägerkappe und Eure Bestienjägertunika.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9001] = { title = "Das Beste gibt's zum Schluss", description = "Das ist ja eine unglaubliche Geschichte, $n! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.", objectives = "Gebt Deliana Eure Krone des Magisters und Eure Roben des Magisters.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9002] = { title = "Das Beste gibt's zum Schluss", description = "Das ist ja eine unglaubliche Geschichte, $n! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.", objectives = "Gebt Deliana Euren Helm des Lichts und Eure Brustplatte des Lichts.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
